SELECT notice_id, machine_id, CAST(position AS TEXT) AS position, typeof(position) AS position_class, kind, project_id, CAST(epoch AS TEXT) AS epoch, CAST(created_at AS TEXT) AS created_at, typeof(created_at) AS created_class, CAST(expires_at AS TEXT) AS expires_at, typeof(expires_at) AS expiry_class, CAST(updated_at AS TEXT) AS updated_at, typeof(updated_at) AS updated_class FROM machine_control_project_notices WHERE machine_id=? AND position>CAST(? AS INTEGER) ORDER BY position;
